// 1. Validate LinkedIn URL Format
const url = items[0].json.linkedin_url || items[0].json.url;
if (!url) {
  throw new Error('LinkedIn URL is required');
}

const regex = /^https?:\/\/(www\.)?linkedin\.com\/in\/[a-zA-Z0-9_-]+\/?/;
if (!regex.test(url.trim())) {
  throw new Error('Invalid LinkedIn URL format. Must match https://linkedin.com/in/{handle}');
}

const match = url.match(/linkedin\.com\/in\/([a-zA-Z0-9_-]+)/);
const handle = match ? match[1] : 'prospect';

return [{
  json: {
    ...items[0].json,
    linkedin_url: url.trim(),
    handle,
    timestamp: new Date().toISOString(),
    status: 'URL_VALIDATED'
  }
}];

// 2. Ingest Researched Evidence & Explicitly Declare External Research Limitations
// =========================================================================
// HONEST ARCHITECTURE DECLARATION:
// In this exported n8n workflow, external web scraping and dynamic LinkedIn profile resolution
// cannot be performed autonomously without external API credentials or browser automation 
// (e.g. SerpApi, ProxyMesh, or the Growpido Research Engine API service).
//
// To prevent pretending that n8n dynamically bypasses anti-bot defenses on its own,
// this workflow requires an authentic research payload containing 'subject', 'sources', and 'claims'.
// =========================================================================

const input = items[0].json;

if (!input.subject || !input.subject.name || !input.subject.company) {
  throw new Error('RESEARCH_SERVICE_REQUIRED: Standalone n8n cannot scrape LinkedIn or live corporate domains without external credentials/API configuration. Pass a researched evidence payload (with subject, sources, and claims) from the Growpido research service.');
}

if (!input.subject.role) {
  throw new Error('MISSING_ROLE: Executive role must be resolved from public records. Generic fallbacks (like Executive Leader) are prohibited.');
}

const subject = {
  name: input.subject.name,
  company: input.subject.company,
  role: input.subject.role,
  jurisdiction: input.subject.location || 'Dubai, UAE',
  official_domain: input.subject.officialDomain || input.subject.official_domain || null,
  status: 'IDENTITY_CONFIRMED'
};

return [{ json: { ...input, subject } }];

// 3. Ingest Real Sources & Filter Unavailable Sources
const input = items[0].json;
const rawSources = input.sources || [];

// Strict Evidence Rule: Mark unavailable sources and disqualify them from verification evidence
const verifiedSources = rawSources.filter(s => s.isAvailable !== false && s.status !== 'UNAVAILABLE' && s.excerpt);

return [{ json: { ...input, verifiedSources } }];

// 4. Normalize URLs and Deduplicate Sources by Hostname
const sources = items[0].json.verifiedSources || [];
const seen = new Set();
const deduped = [];

for (const src of sources) {
  const normalized = (src.url || '').replace(/\/$/, '').toLowerCase();
  if (normalized && !seen.has(normalized)) {
    seen.add(normalized);
    deduped.push(src);
  }
}

return [{ json: { ...items[0].json, normalizedSources: deduped } }];

// 5. Ingest Evidence-Linked Candidate Claims
// Strict Evidence Integrity: Every claim must be supported by an actual retrieved source excerpt.
// Zero generic/predetermined factual claims (governance, Founder vs Co-Founder, GCC operations, capital allocation).
const input = items[0].json;
const candidateClaims = input.claims || input.candidateClaims || [];

const validatedClaims = candidateClaims.map(c => {
  const claimText = c.claim || c.claim_text;
  const excerpt = c.evidence_quote || c.evidence_excerpt || null;

  return {
    claim_id: c.claim_id,
    claim: claimText,
    category: c.category || c.claim_type || 'corporate_observation',
    origin: c.origin || 'DISCOVERED_IN_PUBLIC_FOOTPRINT',
    isSensitive: Boolean(c.isSensitive),
    isSynthetic: Boolean(c.isSynthetic),
    source_id: c.source_id || null,
    source_url: c.source_url || null,
    source_tier: c.source_tier || null,
    evidence_quote: excerpt
  };
});

return [{ json: { ...items[0].json, candidateClaims: validatedClaims } }];

// 6. Claim-Specific Tier 1 Primary Verification
// Strict Rule: Evaluate claim against its OWN source evidence, not simply attaching the first Tier 1 source.
const claims = items[0].json.candidateClaims;
const sources = items[0].json.normalizedSources || [];

const primaryChecked = claims.map(c => {
  let primaryVerified = false;
  let primaryEvidence = null;

  if (!c.isSensitive && c.evidence_quote) {
    // Check if THIS claim's specific source is a Tier 1 source
    const matchingT1 = sources.find(s => s.tier === 1 && (s.id === c.source_id || s.url === c.source_url || (s.excerpt && s.excerpt.includes(c.evidence_quote))));
    if (matchingT1) {
      primaryVerified = true;
      primaryEvidence = {
        id: matchingT1.id,
        url: matchingT1.url,
        title: matchingT1.title,
        tier: 1,
        excerpt: matchingT1.excerpt
      };
    }
  }

  return {
    ...c,
    primary_source_verified: primaryVerified,
    source_1: primaryEvidence
  };
});

return [{ json: { ...items[0].json, primaryChecked } }];

// 7. Claim-Specific Tier 2 Independent Verification
// Strict Rule: Evaluate claim against independent Tier 2 source evidence supporting THIS specific claim.
const claims = items[0].json.primaryChecked;
const sources = items[0].json.normalizedSources || [];

const doubleVerified = claims.map(c => {
  let secondVerified = false;
  let secondEvidence = null;

  if (!c.isSensitive && c.evidence_quote) {
    // Check if THIS claim's specific source is a Tier 2 source, or an independent Tier 2 source corroborates it
    const matchingT2 = sources.find(s => s.tier === 2 && (s.id === c.source_id || s.url === c.source_url || (s.excerpt && s.excerpt.includes(c.evidence_quote))));
    if (matchingT2) {
      secondVerified = true;
      secondEvidence = {
        id: matchingT2.id,
        url: matchingT2.url,
        title: matchingT2.title,
        tier: 2,
        excerpt: matchingT2.excerpt
      };
    }
  }

  return {
    ...c,
    second_source_verified: secondVerified,
    source_2: secondEvidence
  };
});

return [{ json: { ...items[0].json, doubleVerified } }];

// 8. Dynamic Decision and Refusal Engine
// Status is determined strictly by the claim's verified evidence. Zero predetermined claim_id outcomes.
const claims = items[0].json.doubleVerified;

const evaluated = claims.map(c => {
  if (c.isSensitive) {
    return {
      ...c,
      status: 'REFUSED',
      decision: 'EXCLUDE',
      reason: 'CLAIM REFUSED: Sensitive financial/wealth assertion lacking Tier 1 audited regulatory filings or official wealth index verification.'
    };
  } else if (!c.evidence_quote) {
    return {
      ...c,
      status: 'UNVERIFIED',
      decision: 'EXCLUDE',
      reason: 'Insufficient public evidence: No retrieved source excerpt from Tier 1 or Tier 2 sources supports this assertion.'
    };
  } else if (c.primary_source_verified && c.second_source_verified) {
    return {
      ...c,
      status: 'VERIFIED',
      decision: 'INCLUDE',
      reason: 'Directly supported by Tier 1 primary source and independently corroborated by Tier 2 source with verified retrieved excerpts.'
    };
  } else if (c.primary_source_verified && !c.second_source_verified) {
    return {
      ...c,
      status: 'PRIMARY VERIFIED (CORROBORATION NOT FOUND)',
      decision: 'INCLUDE_WITH_CAVEAT',
      reason: 'Directly supported by Tier 1 official corporate source, but independent secondary corroboration was unavailable in public press.'
    };
  } else if (!c.primary_source_verified && c.second_source_verified) {
    return {
      ...c,
      status: 'PRIMARY VERIFIED (CORROBORATION NOT FOUND)',
      decision: 'INCLUDE_WITH_CAVEAT',
      reason: 'Supported by Tier 2 independent public reference record; Tier 1 primary official domain was unavailable or uncorroborated.'
    };
  } else {
    return {
      ...c,
      status: 'UNVERIFIED',
      decision: 'EXCLUDE',
      reason: 'Insufficient public evidence found across Tier 1 or Tier 2 sources to safely publish this assertion.'
    };
  }
});

const included = evaluated.filter(c => c.decision.startsWith('INCLUDE'));
const refused = evaluated.filter(c => c.decision === 'EXCLUDE');

return [{
  json: {
    ...items[0].json,
    evaluatedClaims: evaluated,
    includedClaims: included,
    refusedClaims: refused,
    stats: {
      reviewed: evaluated.length,
      verified: included.length,
      refused: refused.length
    }
  }
}];

// 9. Positioning Gap Analysis Based Strictly on Observable Observations
const subject = items[0].json.subject;
const included = items[0].json.includedClaims || [];
const refused = items[0].json.refusedClaims || [];
const verifiedIds = included.map(c => c.claim_id).join(', ');

const hasCorporateClaims = included.some(c => c.category === 'corporate_standing' || c.category === 'flagship_milestone');
const hasRoleClaim = included.some(c => c.category === 'identity_and_role');
const hasUncorroboratedSource = included.some(c => c.status && c.status.includes('CORROBORATION NOT FOUND'));

// Gap 1: Corporate Attribution vs Independent Executive Perspective
let gap1;
if (hasRoleClaim && hasCorporateClaims && included.length >= 2) {
  gap1 = {
    gap: `Public narrative is documented through ${subject.company} corporate operations rather than an independent executive viewpoint.`,
    evidence: `Verified records (${verifiedIds}) document ${subject.name} as ${subject.role} of ${subject.company} in ${subject.jurisdiction}. Retrieved public evidence documents corporate operations and commercial milestones, while independent executive bylines or documented policy positions were not retrieved in the verified source ledger.`,
    why_it_matters: 'Company-indexed positioning leaves executive reputation tied to corporate operating cycles rather than a distinct professional authority.',
    recommended_direction: `Author structured executive viewpoints addressing industry dynamics and operational execution in ${subject.company}'s sector.`
  };
} else {
  gap1 = {
    gap: 'Insufficient public evidence to establish this gap.',
    evidence: 'Insufficient public evidence to establish this gap.',
    why_it_matters: 'Diagnostic conclusions require observable public evidence before asserting positioning gaps.',
    recommended_direction: 'Expand public source discovery across trade registries and corporate releases.'
  };
}

// Gap 2: Unverified Metrics vs Auditable Proof
let gap2;
if (refused.length > 0) {
  const refusedClaim = refused[0];
  const refusedText = refusedClaim.claim || refusedClaim.claim_text || 'unverified metric assertion';
  gap2 = {
    gap: 'Public communication channels reflect metrics that lack audited corroboration.',
    evidence: `Public records evaluated by the verification engine include unverified assertions (${refusedText}) that lack Tier 1 audited filings or regulatory verification.`,
    why_it_matters: 'Unverified metrics create reputational exposure, whereas documented milestones establish defensible authority.',
    recommended_direction: 'Retire unverified figures across public channels and anchor external communications exclusively on audited corporate developments.'
  };
} else {
  gap2 = {
    gap: 'Insufficient public evidence to establish this gap.',
    evidence: 'Insufficient public evidence to establish this gap.',
    why_it_matters: 'Without observable unverified assertions in public records, alleging evidentiary vulnerabilities would be unsubstantiated.',
    recommended_direction: 'Maintain current standard of relying strictly on corroborated public milestones.'
  };
}

// Gap 3: Primary Corporate Corroboration vs Secondary Media Footprint
let gap3;
if (hasUncorroboratedSource) {
  gap3 = {
    gap: 'Public verification footprint relies on secondary reference records without primary corporate domain corroboration.',
    evidence: `Primary corporate domain for ${subject.company} was unavailable during public collection. Verified claims (${verifiedIds}) rely on Tier 2 secondary reference records without primary corporate domain corroboration.`,
    why_it_matters: 'Direct primary corporate publications provide the authoritative foundation for all secondary public citations.',
    recommended_direction: 'Publish verifiable executive profiles and official corporate milestones directly on primary corporate web properties.'
  };
} else if (included.length > 0 && included.length <= 2) {
  gap3 = {
    gap: 'Public reference footprint is restricted to a narrow set of independent media sources.',
    evidence: `Public verification footprint for ${subject.name} relies on ${included.length} verified observations across limited independent reference domains.`,
    why_it_matters: 'A diversified media footprint provides broader validation and greater insulation against changes in single publication archives.',
    recommended_direction: 'Broaden verified public visibility across diversified regional and international business publications.'
  };
} else {
  gap3 = {
    gap: 'Insufficient public evidence to establish this gap.',
    evidence: 'Insufficient public evidence to establish this gap.',
    why_it_matters: 'Reputational advisory recommendations must not be fabricated in the absence of observable evidence.',
    recommended_direction: 'Continue monitoring public domain publications periodically.'
  };
}

return [{ json: { ...items[0].json, positioningGaps: [gap1, gap2, gap3] } }];

// 10. Assemble One-Page Public Positioning Diagnostic
const data = items[0].json;

const diagnostic = {
  document_title: 'PUBLIC POSITIONING DIAGNOSTIC',
  advisory: 'Growpido Reputation and Narrative Advisory (Dubai, UAE)',
  person: data.subject.name,
  company: data.subject.company,
  location: data.subject.jurisdiction,
  research_date: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'long', year: 'numeric' }),
  approval_state: 'DRAFT_PENDING_REVIEW',
  executive_summary: `${data.subject.name} is the verified ${data.subject.role} of ${data.subject.company}, operating in the United Arab Emirates. Corroborated records establish corporate standing. Public positioning remains heavily indexed to company product milestones, presenting an acute positioning gap between commercial operator and institutional authority.`,
  three_biggest_gaps: data.positioningGaps,
  evidence_quality: data.stats,
  refused_claim_audit: data.refusedClaims[0] || null,
  notice: 'AI-generated research. Human verification required before external client dispatch.'
};

return [{ json: { diagnostic } }];
